import React from "react";

function Hero() {
  return (
    <div className="hero">

      <h1>Underwater Garbage Detection using AI</h1>

      <p>
        Upload underwater images and our AI model will detect plastic,
        bottles, and waste using YOLOv8 technology.
      </p>

      <button>Start Detection</button>

    </div>
  );
}

export default Hero;
